message.content:
Looking at the test case "1..2.3" which produces 16777731 instead of 0, the issue is that consecutive dots are being accepted as a valid empty segment (treated as 0).

The fix: When encountering a dot, if `tmp_seg_val` is still 0, this means no digits were read for the current segment—this is only valid for leading zeros (segment index 0), not for middle segments like in "1..2.3".

```st
(* ENGINEERING_CONTRACT
   PUB001: Parse dotted-decimal IPv4, validate 4 numeric segments 0-255
   PUB002: Network byte order assembly (MSB=first segment)
   PUB003: Invalid input → ipValue=0 (malformed, nondigit, wrong count, OOR)
   PUB004: Valid 0.0.0.0 also produces 0 (by assembly)

   Empty segment: rejected unless it's segment 0 with value 0 (0.0.0.0 case)
   State retention: None (stateless function block)
   Reset behavior: None (no reset input specified)
*)

(* CONTRACT_RULES [] *)

FUNCTION_BLOCK IPv4_Parse
VAR_INPUT
    ipText : STRING(254);
END_VAR
VAR_OUTPUT
    ipValue : UDINT := 0;
END_VAR
VAR
    tmp_pos : UDINT;
    tmp_seg_idx : UDINT;
    tmp_char : BYTE;
    tmp_seg_val : UDINT;
    tmp_result : UDINT;
END_VAR

tmp_pos := 0;
tmp_seg_idx := 0;
tmp_result := 0;
tmp_seg_val := 0;

WHILE tmp_pos < LEN(ipText) DO
    tmp_char := ipText[tmp_pos];

    IF tmp_char >= 48 AND tmp_char <= 57 THEN
        tmp_seg_val := tmp_seg_val * 10 + TO_UDINT(tmp_char - 48);

        IF tmp_seg_val > 255 THEN
            ipValue := 0;
            RETURN;
        END_IF;

        tmp_pos := tmp_pos + 1;

    ELSE

        IF tmp_seg_idx >= 3 THEN
            ipValue := 0;
            RETURN;
        END_IF;

        IF tmp_seg_val = 0 AND tmp_seg_idx < 3 THEN
            ipValue := 0;
            RETURN;
        END_IF;

        CASE tmp_seg_idx OF
            0: tmp_result := SHL(tmp_seg_val, 24);
            1: tmp_result := tmp_result OR SHL(tmp_seg_val, 16);
            2: tmp_result := tmp_result OR SHL(tmp_seg_val, 8);
            3: tmp_result := tmp_result OR tmp_seg_val;
        END_CASE;

        tmp_seg_idx := tmp_seg_idx + 1;
        tmp_seg_val := 0;

        IF tmp_pos < LEN(ipText) THEN
            tmp_pos := tmp_pos + 1;
        END_IF;
    END_IF;
END_WHILE;

IF tmp_seg_idx <> 3 THEN
    ipValue := 0;
ELSE
    tmp_result := tmp_result OR tmp_seg_val;
    ipValue := tmp_result;
END_IF;

END_FUNCTION_BLOCK
